PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE account_migration_state (
  migration_key TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE accounts (
  account_id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  name_key TEXT NOT NULL,
  callsign TEXT NOT NULL DEFAULT '',
  password_salt TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  password_hash_version TEXT NOT NULL DEFAULT 'gas-v3',
  status TEXT NOT NULL CHECK (status IN ('pending', 'approved', 'deactivated', 'denied', 'removed')),
  role TEXT NOT NULL DEFAULT 'member' CHECK (role IN ('member', 'leader', 'admin', 'commander')),
  created_at TEXT NOT NULL,
  activated_at TEXT NOT NULL DEFAULT '',
  approved_by TEXT NOT NULL DEFAULT '',
  admin_changed_at TEXT NOT NULL DEFAULT '',
  admin_changed_by TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL
, permissions_override_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE account_audit (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  created_at TEXT NOT NULL,
  account_id TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT '',
  callsign TEXT NOT NULL DEFAULT '',
  action TEXT NOT NULL,
  actor_name TEXT NOT NULL DEFAULT ''
, source_key TEXT NOT NULL DEFAULT '');
CREATE TABLE auth_sessions (
  token_hash TEXT PRIMARY KEY,
  account_id TEXT NOT NULL REFERENCES accounts(account_id),
  expires_at INTEGER NOT NULL,
  created_at INTEGER NOT NULL,
  remember_me INTEGER NOT NULL DEFAULT 0 CHECK (remember_me IN (0, 1))
);
CREATE TABLE auth_login_attempts (
  login_key TEXT PRIMARY KEY,
  window_started_at INTEGER NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE account_presence (
  account_id TEXT PRIMARY KEY REFERENCES accounts(account_id),
  last_seen INTEGER NOT NULL
);
CREATE TABLE members (
  callsign TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  rank TEXT NOT NULL DEFAULT '',
  date TEXT NOT NULL DEFAULT '',
  rank_assigned_date TEXT NOT NULL DEFAULT '',
  days_in_rank INTEGER NOT NULL DEFAULT 0,
  discord_id TEXT NOT NULL DEFAULT '',
  notes TEXT NOT NULL DEFAULT '',
  has_basic_firefighting INTEGER NOT NULL DEFAULT 0,
  has_advanced_firefighting INTEGER NOT NULL DEFAULT 0,
  has_supervisor_exam INTEGER NOT NULL DEFAULT 0,
  has_hert INTEGER NOT NULL DEFAULT 0,
  activity TEXT NOT NULL DEFAULT 'Active',
  instructor_type TEXT NOT NULL DEFAULT '',
  do_not_promote INTEGER NOT NULL DEFAULT 0,
  sheet_row INTEGER,
  synced_at TEXT NOT NULL
, do_not_terminate INTEGER NOT NULL DEFAULT 0);
CREATE TABLE callsign_slots (
    rank TEXT NOT NULL,
    callsign TEXT NOT NULL,
    sheet_row INTEGER,
    synced_at TEXT NOT NULL,
    PRIMARY KEY (rank, callsign),
    UNIQUE (callsign)
  );
CREATE TABLE training_hours_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  log_date TEXT NOT NULL,
  callsign TEXT NOT NULL,
  member_name TEXT NOT NULL,
  action TEXT NOT NULL,
  previous_time TEXT NOT NULL DEFAULT '',
  new_time TEXT NOT NULL DEFAULT '',
  changed_by TEXT NOT NULL DEFAULT ''
);
CREATE TABLE operational_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  source_key TEXT NOT NULL DEFAULT '',
  kind TEXT NOT NULL,
  log_date TEXT NOT NULL,
  callsign TEXT NOT NULL DEFAULT '',
  member_name TEXT NOT NULL DEFAULT '',
  action TEXT NOT NULL DEFAULT '',
  details TEXT NOT NULL DEFAULT '',
  changed_by TEXT NOT NULL DEFAULT '',
  old_rank TEXT NOT NULL DEFAULT '',
  new_rank TEXT NOT NULL DEFAULT '',
  old_callsign TEXT NOT NULL DEFAULT '',
  new_callsign TEXT NOT NULL DEFAULT ''
);
CREATE TABLE notifications (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  kind TEXT NOT NULL,
  event_key TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  message TEXT NOT NULL,
  callsign TEXT NOT NULL DEFAULT '',
  target_rank TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL
);
CREATE TABLE notification_state (
  state_key TEXT PRIMARY KEY,
  state_value TEXT NOT NULL
);
CREATE TABLE notification_reads (
  account_id TEXT NOT NULL,
  notification_id INTEGER NOT NULL REFERENCES notifications(id) ON DELETE CASCADE,
  read_at TEXT NOT NULL,
  PRIMARY KEY(account_id, notification_id)
);
CREATE TABLE IF NOT EXISTS "training_hours" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  source_row INTEGER UNIQUE,
  callsign TEXT NOT NULL,
  name TEXT NOT NULL,
  training_date TEXT NOT NULL,
  time TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL DEFAULT ''
);
CREATE TABLE IF NOT EXISTS "role_permissions" (
  role TEXT PRIMARY KEY,
  permissions_json TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL DEFAULT ''
, sort_order INTEGER NOT NULL DEFAULT 100, display_name TEXT NOT NULL DEFAULT '', scopes_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE loi_entries (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  type TEXT NOT NULL CHECK (type IN ('HERT', 'FORT')),
  callsign TEXT NOT NULL,
  name TEXT NOT NULL,
  test_percent REAL,
  source_row INTEGER,
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL DEFAULT '',
  UNIQUE(type, callsign)
);
CREATE TABLE notification_hidden (
  account_id TEXT NOT NULL,
  notification_id INTEGER NOT NULL REFERENCES notifications(id) ON DELETE CASCADE,
  hidden_at TEXT NOT NULL,
  PRIMARY KEY(account_id, notification_id)
);
CREATE TABLE notification_preferences (
  account_id TEXT NOT NULL,
  kind TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1,
  PRIMARY KEY(account_id, kind)
);
CREATE TABLE role_permission_history (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  role TEXT NOT NULL,
  changed_at TEXT NOT NULL,
  changed_by TEXT NOT NULL DEFAULT '',
  before_json TEXT NOT NULL DEFAULT '{}',
  after_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE promotion_confirmations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  callsign TEXT NOT NULL DEFAULT '',
  name TEXT NOT NULL DEFAULT '',
  old_rank TEXT NOT NULL DEFAULT '',
  new_rank TEXT NOT NULL DEFAULT '',
  old_callsign TEXT NOT NULL DEFAULT '',
  new_callsign TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  created_by TEXT NOT NULL DEFAULT '',
  portal_done INTEGER NOT NULL DEFAULT 0,
  discord_done INTEGER NOT NULL DEFAULT 0,
  confirmed_at TEXT,
  confirmed_by TEXT NOT NULL DEFAULT ''
, action TEXT NOT NULL DEFAULT 'Promotion', needs_discord INTEGER NOT NULL DEFAULT 1, required_permissions TEXT NOT NULL DEFAULT 'promotion_manage,rank_manage');
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX accounts_name_key_unique
  ON accounts(name_key) WHERE status NOT IN ('removed', 'denied');
CREATE INDEX accounts_callsign_idx ON accounts(callsign);
CREATE INDEX accounts_status_role_idx ON accounts(status, role);
CREATE INDEX account_audit_created_at_idx
  ON account_audit(created_at DESC, id DESC);
CREATE INDEX account_audit_account_id_idx
  ON account_audit(account_id, id DESC);
CREATE INDEX auth_sessions_account_id_idx ON auth_sessions(account_id);
CREATE INDEX auth_sessions_expires_at_idx ON auth_sessions(expires_at);
CREATE INDEX auth_login_attempts_window_idx
  ON auth_login_attempts(window_started_at);
CREATE INDEX account_presence_last_seen_idx
  ON account_presence(last_seen);
CREATE INDEX members_name_idx
  ON members(name);
CREATE INDEX members_rank_idx
  ON members(rank);
CREATE INDEX members_activity_idx
  ON members(activity);
CREATE INDEX members_name_rank_idx
  ON members(name, rank);
CREATE INDEX training_hours_log_date_idx
  ON training_hours_log(log_date DESC, id DESC);
CREATE INDEX operational_logs_kind_date_idx
  ON operational_logs(kind, log_date DESC, id DESC);
CREATE UNIQUE INDEX operational_logs_source_unique
  ON operational_logs(source_key) WHERE source_key<>'';
CREATE UNIQUE INDEX account_audit_source_unique
  ON account_audit(source_key) WHERE source_key<>'';
CREATE INDEX notifications_created_at_idx
  ON notifications(created_at DESC, id DESC);
CREATE INDEX training_hours_member_date_idx
  ON training_hours(callsign,training_date,id);
CREATE INDEX loi_entries_type_name_idx
  ON loi_entries(type, name COLLATE NOCASE);
CREATE INDEX role_permission_history_id_idx ON role_permission_history(id DESC);
CREATE VIEW members_roster_ordered AS
SELECT * FROM members
ORDER BY CASE substr(upper(callsign), 1, instr(callsign, '-') - 1)
  WHEN 'COM' THEN 0
  WHEN 'CHIEF' THEN 1
  WHEN 'B' THEN 2
  WHEN 'DIV' THEN 3
  WHEN 'C' THEN 4
  WHEN 'E' THEN 5
  WHEN 'L' THEN 6
  WHEN 'M' THEN 7
  WHEN 'A' THEN 8
  WHEN 'R' THEN 9
  WHEN 'P' THEN 10
  WHEN 'S' THEN 11
  WHEN 'V' THEN CASE
    WHEN CAST(substr(callsign, instr(callsign, '-') + 1) AS INTEGER)
      IN (1,2,3,4,5,6,7,8,9,14,21,22,23,24,25,26,27,28,29,36,37,38,39,40)
    THEN 13 ELSE 12 END
  ELSE 999
END,
CAST(substr(callsign, instr(callsign, '-') + 1) AS INTEGER),
callsign COLLATE NOCASE;
